generator.source:
"""Random 8-bit patterns for the VHDL Count Set Bits testbench.

Like every generator here, only the *input* is produced -- the expected
output is captured by running the reference solution's own simulation, so
the two can never disagree.
"""

WIDTH = 8


def generate(rng, count):
    builders = (_scattered, _high_bits, _single_bit, _run_of_ones)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _bits(value):
    return "".join(str((value >> b) & 1) for b in range(WIDTH - 1, -1, -1))


def _case(name, value, description=""):
    return {"name": name, "stdin": _bits(value) + "\n", "description": description}


def _scattered(rng, index):
    return _case("scattered bits #%d" % index, rng.randrange(1 << WIDTH))


def _high_bits(rng, index):
    return _case("top bit set #%d" % index,
                 (1 << (WIDTH - 1)) | rng.randrange(1 << (WIDTH - 1)))


def _single_bit(rng, index):
    position = rng.randrange(WIDTH)
    return _case("one bit, at %d #%d" % (position, index), 1 << position)


def _run_of_ones(rng, index):
    width = rng.randint(1, WIDTH)
    start = rng.randint(0, WIDTH - width)
    return _case("%d adjacent bits #%d" % (width, index),
                 ((1 << width) - 1) << start)
